    listTemplates: {
        parameters: {
            query?: {
                limit?: number;
                cursor?: string;
                /** @description Trimmed case-insensitive search across VI/EN names and descriptions; accents are compared as stored by PostgreSQL. */
                query?: string;
                category?: "GENERAL" | "BIRTHDAY" | "ANNIVERSARY" | "HOLIDAY";
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Public catalog page. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data: {
                            /** Format: uuid */
                            id: string;
                            /** @enum {string} */
                            category: "GENERAL" | "BIRTHDAY" | "ANNIVERSARY" | "HOLIDAY";
                            publishedRevision: {
                                /** Format: uuid */
                                id: string;
                                version: number;
                                /** Format: date-time */
                                publishedAt: string;
                                name: {
                                    vi: string;
                                    en: string;
                                };
                                description: {
                                    vi: string;
                                    en: string;
                                };
                                layout: {
                                    /** @enum {integer} */
                                    version: 1;
                                    /** @enum {string} */
                                    type: "PHOTO_FOCUS" | "COLLAGE";
                                    /** @enum {integer} */
                                    monthCount: 12;
                                    /** @enum {integer} */
                                    maxImagesPerMonth: 4;
                                };
                                presets: {
                                    /** @enum {string} */
                                    id: "classic" | "minimal" | "vibrant";
                                    name: {
                                        vi: string;
                                        en: string;
                                    };
                                }[];
                                price: {
                                    /** @enum {string} */
                                    currency: "USD";
                                    unitPriceMinor: number;
                                };
                            };
                        }[];
                        meta: {
                            nextCursor: string | null;
                            hasMore: boolean;
                        };
                    };
                };
            };
            /** @description Invalid filter, cursor, or limit. */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
